55	const PROCESSING_FEE = 5;
56	
57	const INITIAL_ASSESSMENT_SURCHARGE = 0.1;
58	
59	const BASE_PREMIUMS: Record<string, number> = {
60	  sword: 100,
61	  amulet: 60,
62	  staff: 80,
63	  potion: 40,
64	};
65	
66	const basePremiumForItems = (items: Item[]): number =>
67	  items.reduce((sum, item) => sum + BASE_PREMIUMS[item.type], 0);
68	
69	const withInitialAssessmentSurcharge = (basePremium: number): number =>
70	  basePremium * (1 + INITIAL_ASSESSMENT_SURCHARGE);
71	
72	const quotePremium = (items: Item[]): number =>
73	  Math.round(
74	    withInitialAssessmentSurcharge(basePremiumForItems(items)) + PROCESSING_FEE,
75	  );
76	
77	const runStep = (step: Step): StepResult => {
78	  if (step.op === "quote") return { premium: quotePremium(step.items) };
79	  throw new Error(`Unsupported step: ${step.op}`);
80	};
81	
82	export const runScenario = (scenario: Scenario): ScenarioResult => ({
83	  results: scenario.steps.map(runStep),
84	});
