const BASE_PREMIUMS = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
} as const satisfies Record<string, number>;

type InsurableItemType = keyof typeof BASE_PREMIUMS;

const basePremiumFor = (itemType: string): number =>
  BASE_PREMIUMS[itemType as InsurableItemType];
